/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { of } from 'rxjs';
import { ConfirmDialogService } from '@shared/toolkit/dialog/confirm-dialog.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { IdentityUiService } from './identity-ui.service';

describe('IdentityUiService', () => {
  let confirm: jasmine.SpyObj<ConfirmDialogService>;
  let notify: jasmine.SpyObj<NotifyService>;
  let service: IdentityUiService;

  beforeEach(() => {
    confirm = jasmine.createSpyObj<ConfirmDialogService>('ConfirmDialogService', ['confirm']);
    notify = jasmine.createSpyObj<NotifyService>('NotifyService', ['error']);
    TestBed.configureTestingModule({
      providers: [
        { provide: ConfirmDialogService, useValue: confirm },
        { provide: NotifyService, useValue: notify },
      ],
    });
    service = TestBed.inject(IdentityUiService);
  });

  it('asks to reset credentials with the identity.errors.<reason> text', () => {
    confirm.confirm.and.returnValue(of(true));
    let result: boolean | undefined;

    service.confirmResetCredentials('discovery').subscribe((ok) => (result = ok));

    expect(confirm.confirm).toHaveBeenCalledWith({
      titleKey: 'identity.errors.title',
      messageKey: 'identity.errors.discovery',
      okKey: 'identity.errors.reset',
    });
    expect(result).toBeTrue();
  });

  it('notifies errors with the identity.errors.<reason> text', () => {
    service.notifyError('code');
    expect(notify.error).toHaveBeenCalledWith('identity.errors.code');
  });
});
